private:
    int* p;
    int r, c;
public:
    Array2(int row=0, int col=0): r(row), c(col) {
        if (row*col > 0) p = new int[row*col];
        else p = NULL;
    }
    ~Array2() { if(p) delete [] p; }
    Array2(const Array2& a): r(a.r), c(a.c) {
        if (r*c > 0) {
            p = new int[r*c];
            memcpy(p, a.p, sizeof(int)*r*c);
        } else p = NULL;
    }
    Array2& operator=(const Array2& a) {
        if (this == &a) return *this;
        if (p) delete [] p;
        r = a.r; c = a.c;
        if (r*c > 0) {
            p = new int[r*c];
            memcpy(p, a.p, sizeof(int)*r*c);
        } else p = NULL;
        return *this;
    }
    int* operator[](int i) { return p + i*c; }
    int operator()(int i, int j) { return p[i*c + j]; }

