private:
    vector<int> d;
public:
    CHugeInt() {}
    CHugeInt(const char* s) {
        int n = strlen(s);
        d.resize(n);
        for (int i = 0; i < n; i++) d[i] = s[n-1-i] - '0';
    }
    CHugeInt(int n) { *this = n; }
    CHugeInt& operator=(int n) {
        d.clear();
        if (n == 0) { d.push_back(0); return *this; }
        while (n) { d.push_back(n%10); n/=10; }
        return *this;
    }
    CHugeInt operator+(const CHugeInt& b) const {
        CHugeInt r;
        int c = 0;
        int n = max(d.size(), b.d.size());
        for (int i = 0; i < n || c; i++) {
            int x = c;
            if (i < d.size()) x += d[i];
            if (i < b.d.size()) x += b.d[i];
            r.d.push_back(x%10);
            c = x/10;
        }
        return r;
    }
    friend CHugeInt operator+(int n, const CHugeInt& a) {
        CHugeInt t(n);
        return t + a;
    }
    CHugeInt operator+(int n) const {
        CHugeInt t(n);
        return *this + t;
    }
    CHugeInt& operator+=(int n) {
        *this = *this + n;
        return *this;
    }
    CHugeInt& operator++() {
        *this = *this + 1;
        return *this;
    }
    CHugeInt operator++(int) {
        CHugeInt tmp = *this;
        *this = *this + 1;
        return tmp;
    }
    friend ostream& operator<<(ostream& os, const CHugeInt& a) {
        for (int i = a.d.size()-1; i >= 0; i--) os << a.d[i];
        return os;
    }
